after":{"title":"Heden ik","author_id":987312004,"first_publish_year":1993,"open_library_id":"OL1667577W","cover_id":null,"source_type":"open_library","work_type":null,"native_identity_key":"nlscale:20261102:ol:OL1667577W","id":987140007}},{"ref":"e6","relation":"editions","key":{"open_library_edition_id":"OL1502793M"},"before":null,"after":{"work_id":"@w6","open_library_edition_id":"OL1502793M","isbn_13":"9789025402266","isbn_10":null,"title":"Heden ik","language":"dut","publisher":"Contact","id":987240007,"publish_date":null,"cover_id":null}},{"ref":"d6","relation":"catalog_work_descriptions","key":{"work_id":"@w6","language":"nl"},"before":null,"after":{"work_id":"@w6","language":"nl","bound_author_id":987312004,"text":"Renate Dorrestein beschrijft hoe ziekte haar vertrouwde leven onderbreekt. Werk, dagelijkse bezigheden en contact met anderen krijgen een andere betekenis wanneer haar lichaam niet meer doet wat zij verwacht. Haar zoektocht naar erkenning brengt ook de reacties van artsen en haar omgeving in beeld. In dit persoonlijke relaas over leven met ME onderzoekt zij wat er gebeurt met zelfstandigheid en zelfbeeld. Haar persoonlijke relaas laat zien hoe moeilijk het is uit te leggen wat voor de buitenwereld niet zichtbaar is.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://pure.uva.nl/ws/files/36436087/Een_wandelende_anomalie.pdf","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p104756799"],"reference":"new-work-dossier-readings-041.json#197","checked_at":"2026-11-03T08:39:50.360Z","note":"HedenIk1993, exactDutchPaperback9789025402266, Dorrestein literary illness memoir, notclinical instruction orfiction."},{"type":"original_substantive_source_review","sources":["https://pure.uva.nl/ws/files/36436087/Een_wandelende_anomalie.pdf","https://www.patientervaringsverhalen.nl/wp-content/uploads/2021/07/bijlagen/Dorrestein.pdf","https://data.bib